    int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}LinearLayout row(){return new LinearLayout(this);}TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1);return t;}
